export function quickFoodCandidates(db){const aiKeys=new Set((db.meals||[]).filter(m=>/^ai-/.test(m.source||'')).map(m=>foodKey(m))),result=[],seen=new Set(),catalog=new Map((db.foods||[]).filter(item=>item.catalog||item.source==='대표값').map(item=>[foodKey(item),item])),preferred=new Map((db.foods||[]).filter(item=>!item.catalog&&item.source!=='대표값').map(item=>[foodKey(item),item]));for(const item of [...recentFoods(db.meals||[],20),...recentFoods((db.meals||[]).filter(m=>/^ai-/.test(m.source||'')),500),...(db.foods||[])]){const key=foodKey(item);if(seen.has(key))continue;seen.add(key);const chosen=preferred.get(key)||item,base=catalog.get(key);result.push(base&&chosen!==base&&!chosen.catalog&&differs(perUnit(chosen),base)?{...chosen,personal:true,group:chosen.group||base.group,aliases:chosen.aliases||base.aliases}:!base&&aiKeys.has(key)?{...chosen,personal:true}:chosen)}return result}
