export function yesterdayMeal(meals=[],date,time){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()-1);const p=n=>String(n).padStart(2,'0'),y=`${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`;const [h,mi]=String(time||'12:00').split(':').map(Number),target=h*60+mi;const groups=new Map();for(const m of meals){if(m.date!==y||m.planned)continue;const k=m.mealGroupId||`legacy:${m.slot}`;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(m)}let best=null;for(const items of groups.values()){const t=new Date(items[0].loggedAt);const mins=t.getHours()*60+t.getMinutes(),gap=Math.abs(mins-target);if(gap<=180&&(!best||gap<best.gap))best={gap,items,at:`${p(t.getHours())}:${p(t.getMinutes())}`}}return best}
export function mealToRow(m){const f=MASS.has(m.servingUnit)?Number(m.servingQty)/100:Number(m.servingQty)||1;const per=k=>m[k]==null?null:Math.round(m[k]/f*10)/10;return {name:m.name,servingQty:m.servingQty,servingUnit:m.servingUnit,...(m.unitGrams?{unitGrams:m.unitGrams}:{}),calories:per('calories'),carbs:per('carbs'),protein:per('protein'),fat:per('fat'),source:m.source||'manual'}}
export function usualQty(meals=[],name,unit){const m=new Map();for(const x of meals){if(x.planned||x.name!==name||(x.servingUnit||'g')!==(unit||'g'))continue;const q=Number(x.servingQty);if(!(q>0))continue;m.set(q,(m.get(q)||0)+1)}return [...m.entries()].sort((a,b)=>b[1]-a[1]||a[0]-b[0]).slice(0,3).map(([qty,count])=>({qty,count}))}
