export function quickMealRecords(state){if(!state.rows.length)throw Error('음식을 하나 이상 골라 주세요.');const groupId=state.groupId!==undefined?state.groupId:uid(),loggedAt=new Date(`${state.date}T${state.time}:00`).toISOString();if(!Number.isFinite(new Date(loggedAt).getTime()))throw Error('식사 시각을 확인해 주세요.');const planned=isFuture(loggedAt);return state.rows.map(row=>cleanMeal({...row,...foodValues(row),aiEstimate:scaleEstimate(row.aiEstimate,factor(row)),id:uid(),date:state.date,slot:state.slot||'식사',mealGroupId:groupId,loggedAt,planned}))}
const goal=(key,label,actual,target,unit)=>{const pct=target>0?actual/target*100:0,over=Math.max(actual-target,0);return `<div class="nutrition-goal ${key}"><div class="nutrition-goal-head"><strong>${label}</strong><span>${fmt(actual,1)} / ${fmt(target,1)} ${unit}</span></div><div class="nutrition-track"><i style="width:${Math.min(100,pct)}%"></i>${over?`<b style="width:${Math.min(30,pct-100)}%"></b>`:''}</div><small>${target<=0?'목표 미설정':over?`${fmt(over,1)} ${unit} 초과`:`${fmt(target-actual,1)} ${unit} 남음`}</small></div>`};
