export function recentMealGroups(meals=[],date,limit=3){const d0=new Date(`${date}T12:00:00`).getTime(),groups=new Map();for(const m of meals){if(m.planned||!m.date||m.date>=date)continue;if((d0-new Date(`${m.date}T12:00:00`).getTime())/86400000>14)continue;const k=m.mealGroupId||`${m.date}|${m.slot}`;if(!groups.has(k))groups.set(k,{key:k,date:m.date,slot:m.slot,at:m.loggedAt||m.date,items:[]});groups.get(k).items.push(m)}const seen=new Set(),out=[];for(const g of [...groups.values()].sort((a,b)=>String(b.at).localeCompare(String(a.at)))){const sig=g.items.map(x=>x.name).sort().join('|');if(seen.has(sig)||!g.items.length)continue;seen.add(sig);out.push(g);if(out.length>=limit)break}return out}
