export const comboSig = names => [...new Set(names.map(n => String(n).trim()).filter(Boolean))].sort().join('|');
export function frequentCombo(db, rows) {
  if (!rows || rows.length < 2) return null;
  const sig = comboSig(rows.map(r => r.name)), groups = new Map();
  for (const m of db.meals || []) { if (m.planned) continue; const k = m.mealGroupId || `${m.date}|${m.slot}`; if (!groups.has(k)) groups.set(k, []); groups.get(k).push(m.name); }
  const count = [...groups.values()].filter(ns => comboSig(ns) === sig).length;
  if (count < 3) return null;
  if ((db.recipes || []).some(r => comboSig((r.items || []).map(x => x.name)) === sig)) return null;
  if ((db.settings?.comboDismissed || []).includes(sig)) return null;
  return {sig, count};
}
