// 4.17.0 '값 확인 필요' 음식: 왜 의심스러운지 보여 주고, 열량이 0으로 들어간 경우 탄단지로 계산한 값을 사용자가 고르게(자동으로 고치지 않음)
export function doubtNoteHTML(row){if(row?.dbMaybeGone)return '<p class="hint doubt-gone">식약처에 올라온 업체 공식 값이에요. 지금 메뉴판에는 없어 단종됐을 수 있어요.</p>';if(!row?.dbDoubt)return '';const calc=Math.round((row.carbs||0)*4+(row.protein||0)*4+(row.fat||0)*9),sweet=/0 ?kcal|제로|무설탕|알룰로스|에리스리톨|스테비아|슈가\s?프리|sugar ?free|키토/i.test(row.name||'');if(sweet)return `<div class="doubt-note" role="note"><b>이 음식 값은 확인이 필요해요</b><p>제로·무설탕 제품은 탄수화물(당알코올)이 있어도 실제 열량이 거의 없을 수 있어요. 포장 라벨의 열량을 그대로 믿는 게 가장 정확해요.</p></div>`;const zero=row.calories===0&&calc>0,off=row.calories>0&&calc>0&&Math.abs(row.calories-calc)>Math.max(40,row.calories*0.4);return `<div class="doubt-note" role="note"><b>이 음식 값은 확인이 필요해요</b><p>${zero?`열량이 0으로 들어 있지만 탄단지로 계산하면 약 ${calc}kcal예요.`:off?`표시된 열량(${Math.round(row.calories)}kcal)과 탄단지로 계산한 값(약 ${calc}kcal)이 많이 달라요.`:'출처마다 값이 달라 아직 확인하지 못했어요.'} 포장 라벨이 있으면 라벨 값이 가장 정확해요.</p>${zero?`<button type="button" class="button small secondary" id="q-doubt-calc">탄단지로 계산한 ${calc}kcal로 쓰기</button>`:''}</div>`}
// 5.1.0 g 음식을 개수로: 1개 무게로 영양값을 바꾼 한 줄(저장도 '2개'로)
export function countRow(item,cnt,cu){const per=scaleNutrition(item,cu.grams/100);return {...item,...per,servingQty:cnt,servingUnit:cu.unit,unitGrams:cu.grams}}
function quickGramPicker(s){const row=s.picked;if(row&&s.cuFor!==row.name){s.cuFor=row.name;const cu=MASS.has(row.servingUnit||'g')?(row.countUnit||countUnitFor(row.name)):null;s.cu=cu||null;s.useCount=!!(cu&&(cu.default||cu.count)&&s.editIndex<0);s.cnt=1}const cu=s.cu,useC=!!(cu&&s.useCount);if(useC)return countPicker(s,row,cu);return quickGramPickerMass(s)}
function countPicker(s,row,cu){const cnt=Number(s.cnt)||1,n=foodValues(countRow(row,cnt,cu));return `<div class="quick-overlay"><div class="quick-overlay-head"><h3>${esc(row.name)} · 먹은 양</h3><button type="button" class="close" id="q-close-picker">×</button></div>${doubtNoteHTML(row)}${cuSeg(s,cu)}<p class="hint">1${esc(cu.unit)} ≈ ${fmt(cu.grams,1)}g로 영양값을 계산해요.</p><div class="chip-row">${[0.5,1,2,3,4].map(g=>`<button type="button" class="chip ${cnt===g?'active':''}" data-q-cnt="${g}">${g}${esc(cu.unit)}</button>`).join('')}</div><label class="field">직접 입력 · ${esc(cu.unit)}<input id="q-qty" type="number" inputmode="decimal" min="0.1" step="any" value="${esc(cnt)}"></label><p class="quick-food-macro" aria-live="polite">${fmt(n.calories)}kcal · 탄 ${fmt(n.carbs,1)}g · 단 ${fmt(n.protein,1)}g · 지 ${fmt(n.fat,1)}g <small>(${fmt(cnt*cu.grams,1)}g)</small></p><button type="button" class="button" id="q-confirm-food">${s.editIndex>=0?'이 음식만 수정':'이 음식 식사에 담기'}</button></div>`}
const cuSeg=(s,cu)=>`<div class="q-cu-seg" role="group" aria-label="양 단위"><button type="button" class="${s.useCount?'on':''}" data-q-cu="count" aria-pressed="${!!s.useCount}">${esc(cu.unit)}<small>1${esc(cu.unit)}≈${fmt(cu.grams,1)}g</small></button><button type="button" class="${s.useCount?'':'on'}" data-q-cu="mass" aria-pressed="${!s.useCount}">g<small>무게로</small></button></div>`;
function quickGramPickerMass(s){const row=s.picked,options=s.gramOptions||[100,200,210,250,300],unit=row.servingUnit||'g',massU=MASS.has(unit),n=foodValues({...row,servingQty:s.qty});return `<div class="quick-overlay"><div class="quick-overlay-head"><h3>${esc(row.name)} · 먹은 양</h3><button type="button" class="close" id="q-close-picker">×</button></div>${doubtNoteHTML(row)}${s.cu&&massU?cuSeg(s,s.cu):''}<p class="hint">${massU?`100${unit} 기준 영양값 · 먹은 양은 따로 고를 수 있어요.`:`1${unit}${row.unitGrams?`(${row.unitGrams}${/^(잔|병|캔)$/.test(unit)?'ml':'g'})`:''} 기준 영양값 · 수량을 고를 수 있어요.`}</p>${massU?`<div class="chip-row">${options.map(g=>`<button type="button" class="chip ${Number(s.qty)===g?'active':''}" data-q-gram="${g}">${g}${unit}</button>`).join('')}</div>`:`<div class="chip-row">${[0.5,1,1.5,2,3].map(g=>`<button type="button" class="chip ${Number(s.qty)===g?'active':''}" data-q-gram="${g}">${g}${unit}</button>`).join('')}</div>`}${(s.usual||[]).length?`<div class="usual-row"><small>자주 먹은 양</small>${s.usual.map(u=>`<button type="button" class="chip usual ${Number(s.qty)===u.qty?'active':''}" data-q-gram="${u.qty}">${esc(unitLabel(u.qty,unit,row.unitGrams))} <em>${u.count}번</em></button>`).join('')}</div>`:''}<label class="field">직접 입력 · ${esc(unit)}<input id="q-qty" type="number" inputmode="decimal" min="0.01" step="any" value="${esc(s.qty)}"></label>${isShareFood(row.name)?`<div class="share-row" role="group" aria-label="같이 먹은 사람 수"><small>같이 먹었어요 · 고른 양을 사람 수로 나눠 내 몫만 남겨요</small><div class="chip-row">${[1,2,3,4,5].map(p=>`<button type="button" class="chip ${(s.share||1)===p?'active':''}" data-q-share="${p}">${p===1?'혼자':p+'명'}</button>`).join('')}</div>${(s.share||1)>1?`<small class="share-note">저장할 내 몫: ${fmt(s.qty/(s.share||1),2)}${esc(unit)}</small>`:''}</div>`:''}<p class="quick-food-macro" aria-live="polite">${foodMacroText(row,s.qty,s.share)}</p><button type="button" class="button" id="q-confirm-food">${s.editIndex>=0?'이 음식만 수정':'이 음식 식사에 담기'}</button></div>`}
export function quickRecentExercises(db){const result=[],seen=new Set();for(const w of [...(db.workouts||[])].sort((a,b)=>b.date.localeCompare(a.date)))for(const x of w.exercises||[]){const key=x.exerciseId||x.name;if(seen.has(key))continue;seen.add(key);result.push(x)}return result}
export function quickWorkoutRecord(s,db){if(!s.sets.length)throw Error('완료한 세트를 하나 이상 기록해 주세요.');const old=(db.workouts||[]).find(x=>x.id===s.workoutId);const grouped=[];for(const item of s.sets){if(item.timed){grouped.push({...item.exercise,kind:'cardio',exerciseId:item.exerciseId,machineId:null,durationMin:item.durationMin,distanceKm:item.distanceKm,effort:item.effort,avgHr:item.avgHr,sessionType:item.sessionType,note:item.note,completedAt:item.completedAt,...(item.moves?.length?{moves:item.moves}:{}),sets:[]});continue}let x=grouped.find(e=>e.exerciseId===item.exerciseId&&e.machineId===item.machineId&&e.kind!=='cardio');if(!x){const mt=machineTargets(findMachine(db,null,item.machineId),item.exercise);x={...item.exercise,...(mt||{}),exerciseId:item.exerciseId,machineId:item.machineId,sets:[]};if(genericMachine(item.machineId)?.sided==='iso'){x.weightBasis='per-hand';x.handCount=2}grouped.push(x)}x.sets.push({id:item.id,weight:item.weight,originalWeight:item.weight,unit:item.unit,originalUnit:item.unit,reps:item.reps,type:item.type||'본세트',completed:true,completedAt:item.completedAt,...(item.side?{side:item.side}:{}),...(item.restSec>0?{restSec:item.restSec}:{}),...(item.barKg!=null?{barKg:item.barKg}:{}),...(item.levelKg!=null?{levelKg:item.levelKg,...(item.levelEst?{levelEst:true}:{})}:{})})}const times=s.sets.map(x=>x.completedAt).filter(Boolean),planned=times.length>0&&times.every(t=>isFuture(t));return cleanWorkout({...old,planned,id:s.workoutId||undefined,date:s.date,gymName:s.gymName,...(s.targets?.length?{targets:[...s.targets]}:{}),title:s.title||sessionTitle(grouped,s.targets),exercises:grouped,updatedAt:new Date().toISOString()})}
