export function findMachine(db,shared,id,s=null){if(!id)return null;const mine=(db.machines||[]).find(m=>m.id===id);if(mine)return mine;/* 4.18.0 합쳐진 중복 머신의 옛 ID는 남은 ID로 */id=shared?.machineAlias?.[id]||id;if(s?.gymName){const g=brandMachinesAt(shared||{},s.gymName,'',gymKeyOf(db.settings||{},s.gymName)).find(m=>m.id===id);if(g)return g}return genericMachine(id)||(shared?.machineModels||[]).find(m=>m.id===id)||null}
export function machineLabel(m){if(!m)return '프리웨이트 / 머신 미지정';if(m.generic)return `일반 · ${m.name}`;if(m.builtin)return `${m.manufacturer} · ${m.model}`;return `${m.manufacturer||'제조사 모름'} · ${m.model||m.name||'모델 모름'}${m.unit?` · ${m.unit}`:''}`}
